set -eu
test "$(git rev-parse HEAD)" = "4b06a39ebdb8a99d5544b27c8a52f33ad8e42440"
test -z "$(git status --porcelain --untracked-files=all)"
python3 -B - <<'PY'
import subprocess,json,hashlib
from pathlib import Path
files=subprocess.check_output(["git","ls-files","-z","--","server","orchestrator","bin","mcp","scripts","docs","package.json"]).decode().split("\0")
files=[p for p in files if p and Path(p).is_file()]
expected={p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in files}
probe="const fs=require('node:fs'),crypto=require('node:crypto');let x=JSON.parse(fs.readFileSync(0,'utf8'));let out={};for(const p of Object.keys(x)){try{out[p]=crypto.createHash('sha256').update(fs.readFileSync('/app/'+p)).digest('hex')}catch{out[p]=null}}console.log(JSON.stringify(out));"
for service in ("debug-ai","sandbox-runner"):
 cid=subprocess.check_output(["docker","compose","ps","--quiet",service],text=True).strip()
 assert cid
 actual=json.loads(subprocess.check_output(["docker","exec","-i",cid,"node","-e",probe],input=json.dumps(expected),text=True))
 mismatch=[p for p,v in expected.items() if actual.get(p)!=v]
 print("RUNTIME_SOURCE_PARITY "+service+" "+str(len(expected)-len(mismatch))+"/"+str(len(expected)))
 if mismatch: print("MISMATCH_PATHS "+json.dumps(mismatch));raise SystemExit(5)
 inspect=json.loads(subprocess.check_output(["docker","inspect",cid],text=True))[0]
 assert inspect["State"]["Running"]
 print("RUNTIME_RUNNING "+service+" "+inspect["Image"])
 if service=="debug-ai":
  e=dict(s.split("=",1) for s in inspect["Config"]["Env"] if "=" in s)
  assert e.get("DEBUG_AI_ROLE_EXECUTION_MODE")=="six_role"
  assert e.get("DEBUG_AI_CORE_GATE_DISPATCH_MODE")=="model_gates"
  print("RUNTIME_ROLE_MODE=six_role GATE_MODE=model_gates")
